    11→func newCleanCmd() *cobra.Command {
    12→	var forceFlag bool
    13→
    14→	cmd := &cobra.Command{
    15→		Use:   "clean",
    16→		Short: "Clean up orphaned entire's data",
    17→		Long: `Remove orphaned entire's data that wasn't cleaned up automatically.
    18→
    19→This command finds and removes orphaned data from any strategy:
    20→
    21→  Shadow branches (entire/<commit-hash>)
    22→    Created by manual-commit strategy. Normally auto-cleaned when sessions
    23→    are condensed during commits.
    24→
    25→  Session state files (.git/entire-sessions/)
    26→    Track active sessions. Orphaned when no checkpoints or shadow branches
    27→    reference them.
    28→
    29→  Checkpoint metadata (entire/checkpoints/v1 branch)
    30→    For auto-commit checkpoints: orphaned when commits are rebased/squashed
    31→    and no commit references the checkpoint ID anymore.
    32→    Manual-commit checkpoints are permanent (condensed history) and are
    33→    never considered orphaned.
    34→
    35→Without --force, shows a preview of items that would be deleted.
    36→With --force, actually deletes the orphaned items.
    37→
    38→The entire/checkpoints/v1 branch itself is never deleted.`,
    39→		RunE: func(cmd *cobra.Command, _ []string) error {
    40→			return runClean(cmd.OutOrStdout(), forceFlag)
    41→		},
    42→	}
    43→
    44→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Actually delete items (otherwise just preview)")
    45→
    46→	return cmd
    47→}
    48→
    49→func runClean(w io.Writer, force bool) error {
    50→	// List all cleanup items
    51→	items, err := strategy.ListAllCleanupItems()
    52→	if err != nil {
    53→		return fmt.Errorf("failed to list orphaned items: %w", err)
    54→	}
    55→
    56→	return runCleanWithItems(w, force, items)
    57→}
    58→
    59→// runCleanWithItems is the core logic for cleaning orphaned items.
    60→// Separated for testability.
    61→func runCleanWithItems(w io.Writer, force bool, items []strategy.CleanupItem) error {
    62→	// Handle no items case
    63→	if len(items) == 0 {
    64→		fmt.Fprintln(w, "No orphaned items to clean up.")
    65→		return nil
    66→	}
    67→
    68→	// Group items by type for display
    69→	var branches, states, checkpoints []strategy.CleanupItem
    70→	for _, item := range items {
    71→		switch item.Type {
    72→		case strategy.CleanupTypeShadowBranch:
    73→			branches = append(branches, item)
    74→		case strategy.CleanupTypeSessionState:
    75→			states = append(states, item)
    76→		case strategy.CleanupTypeCheckpoint:
    77→			checkpoints = append(checkpoints, item)
    78→		}
    79→	}
    80→
    81→	// Preview mode (default)
    82→	if !force {
    83→		fmt.Fprintf(w, "Found %d orphaned items:\n\n", len(items))
    84→
    85→		if len(branches) > 0 {
    86→			fmt.Fprintf(w, "Shadow branches (%d):\n", len(branches))
    87→			for _, item := range branches {
    88→				fmt.Fprintf(w, "  %s\n", item.ID)
    89→			}
    90→			fmt.Fprintln(w)
    91→		}
    92→
    93→		if len(states) > 0 {
    94→			fmt.Fprintf(w, "Session states (%d):\n", len(states))
    95→			for _, item := range states {
    96→				fmt.Fprintf(w, "  %s\n", item.ID)
    97→			}
    98→			fmt.Fprintln(w)
    99→		}
   100→
   101→		if len(checkpoints) > 0 {
   102→			fmt.Fprintf(w, "Checkpoint metadata (%d):\n", len(checkpoints))
   103→			for _, item := range checkpoints {
   104→				fmt.Fprintf(w, "  %s\n", item.ID)
   105→			}
   106→			fmt.Fprintln(w)
   107→		}
   108→
   109→		fmt.Fprintln(w, "Run with --force to delete these items.")
   110→		return nil
   111→	}
   112→
   113→	// Force mode - delete items
   114→	result, err := strategy.DeleteAllCleanupItems(items)
   115→	if err != nil {
   116→		return fmt.Errorf("failed to delete orphaned items: %w", err)
   117→	}
   118→
   119→	// Report results
   120→	totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints)
   121→	totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints)
   122→
   123→	if totalDeleted > 0 {
   124→		fmt.Fprintf(w, "Deleted %d items:\n", totalDeleted)
   125→
   126→		if len(result.ShadowBranches) > 0 {
   127→			fmt.Fprintf(w, "\n  Shadow branches (%d):\n", len(result.ShadowBranches))
   128→			for _, branch := range result.ShadowBranches {
   129→				fmt.Fprintf(w, "    %s\n", branch)
   130→			}
   131→		}
   132→
   133→		if len(result.SessionStates) > 0 {
   134→			fmt.Fprintf(w, "\n  Session states (%d):\n", len(result.SessionStates))
   135→			for _, state := range result.SessionStates {
   136→				fmt.Fprintf(w, "    %s\n", state)
   137→			}
   138→		}
   139→
   140→		if len(result.Checkpoints) > 0 {
   141→			fmt.Fprintf(w, "\n  Checkpoints (%d):\n", len(result.Checkpoints))
   142→			for _, cp := range result.Checkpoints {
   143→				fmt.Fprintf(w, "    %s\n", cp)
   144→			}
   145→		}
   146→	}
   147→
   148→	if totalFailed > 0 {
   149→		fmt.Fprintf(w, "\nFailed to delete %d items:\n", totalFailed)
   150→
   151→		if len(result.FailedBranches) > 0 {
   152→			fmt.Fprintf(w, "\n  Shadow branches:\n")
   153→			for _, branch := range result.FailedBranches {
   154→				fmt.Fprintf(w, "    %s\n", branch)
   155→			}
   156→		}
   157→
   158→		if len(result.FailedStates) > 0 {
   159→			fmt.Fprintf(w, "\n  Session states:\n")
   160→			for _, state := range result.FailedStates {
   161→				fmt.Fprintf(w, "    %s\n", state)
   162→			}
   163→		}
   164→
   165→		if len(result.FailedCheckpoints) > 0 {
   166→			fmt.Fprintf(w, "\n  Checkpoints:\n")
   167→			for _, cp := range result.FailedCheckpoints {
   168→				fmt.Fprintf(w, "    %s\n", cp)
   169→			}
   170→		}
   171→
   172→		return fmt.Errorf("failed to delete %d items", totalFailed)
   173→	}
   174→
   175→	return nil
   176→}
